def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_actions = [h[0] for h in history]
    opp_actions = [h[1] for h in history]
    opp_defects = sum(1 for a in opp_actions if a == 'D')
    my_defects = sum(1 for a in my_actions if a == 'D')

    if opp_defects == 0:
        if my_defects == 0:
            if n >= 10:
                return 'D'
            return 'C'
        else:
            recent_my = my_actions[-4:] if n >= 4 else my_actions
            if 'D' not in recent_my:
                return 'D'
            return 'C'

    defect_rate = opp_defects / n
    last_me, last_op = history[-1]

    if last_op == 'D':
        if defect_rate > 0.5:
            if rng.random() < 0.1:
                return 'C'
            return 'D'
        elif defect_rate > 0.2:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            if rng.random() < 0.9:
                return 'C'
            return 'D'
    else:
        if defect_rate > 0.5:
            if rng.random() < 0.4:
                return 'D'
            return 'C'
        else:
            if n >= 98 and defect_rate < 0.1:
                return 'D'
            return 'C'
